def page(fn,title,body,cat=None):
    c=f' data-cat="{cat}"' if cat else ''
    open(fn,'w').write(f'''<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{title} | Pawfect</title>
<link rel="preconnect" href="https://fonts.googleapis.com"><link href="https://fonts.googleapis.com/css2?family=Nunito:wght@400;600;700;800;900&display=swap" rel="stylesheet">
<link rel="stylesheet" href="css/style.css"></head><body{c}>{NAV}<main>{body}</main>{FOOT}<script src="js/products.js"></script><script src="js/app.js"></script></body></html>''')
def head(t,p):return f'<div class="pagehead"><div class="wrap"><h1 style="font-size:clamp(2rem,4vw,3rem)">{t}</h1><p>{p}</p></div></div>'
def listing(t,p,cat,search=True):
    return head(t,p)+f'<section><div class="wrap"><div class="tools"><input id="q" type="search" placeholder="Search {t.lower()}" aria-label="Search"><select id="sort" aria-label="Sort"><option value="">Sort: Featured</option><option value="lo">Price: low to high</option><option value="hi">Price: high to low</option></select></div><div class="grid" id="grid"></div></div></section>'
def form(kind,msg,fields,btn):
    return f'<form data-form="{kind}" data-msg="{msg}">{fields}<button class="btn" style="margin-top:1.2rem">{btn}</button><p class="note" role="status"></p></form>'
inp=lambda l,t='text',r=True:f'<label>{l}<input type="{t}" {"required" if r else ""}></label>'
sel=lambda l,o:f'<label>{l}<select>'+''.join(f'<option>{x}</option>' for x in o)+'</select></label>'
# Home
