def pick(h,l,kw,s):return f'<a href="{h}"><div class="pair"><img src="https://loremflickr.com/240/240/{kw}?lock={s}" alt="" loading="lazy" onerror="this.remove()"><img src="https://loremflickr.com/240/240/{kw}?lock={s+20}" alt="" loading="lazy" onerror="this.remove()"></div>{l}</a>'
